"""Manually authored solutions, reviewed individually; helpers only format HTML."""
from render import *
def st(h,math='',why=''): return h,(p(why) if why else '')+(m(math) if math else '')
def giv(text): return st('Givet och sökt',why=text)
def power(math,why=''): return st(r'Elektrisk effekt: \(P=UI\)',math,why)
def heatpower(math='',why=''): return st(r'Effekt i en resistor: \(P=I^2R\)',math,why)
def voltagepower(math='',why=''): return st(r'Effekt i en resistor: \(P=U^2/R\)',math,why)
def energy(math,why=''): return st(r'Energi: \(E=Pt\)',math,why)
def ohm(math,why=''): return st(r'Ohms lag: \(U=RI\)',math,why)
def chargeenergy(math,why=''): return st(r'Elektrisk energi: \(E=UQ\)',math,why)
def charge(math,why=''): return st(r'Laddning: \(Q=It\)',math,why)
def eta(math,why=''): return st(r'Verkningsgrad: \(\eta=E_{\mathrm{nyttig}}/E_{\mathrm{in}}\)',math,why)
def cost(math,why=''): return st(r'Elkostnad: \(K=E\cdot\text{pris per kWh}\)',math,why)
def warmth(math,why=''):return st(r'Uppvärmning: \(Q=mc\Delta T\)',math,why)
def sol(steps,answer):return steps,answer
def hints(id,main,*cards):
 q=byid[id];q['ledtrad']=p(main)
 if cards:
  assert len(cards)==len(q.get('spelDelar',[])),id
  for d,h in zip(q['spelDelar'],cards):d['ledtrad']=p(h)

